  // Buffet Upload & Settings Modals
  const [isBuffetUploadModalOpen, setIsBuffetUploadModalOpen] = useState(false);
  const [isBuffetGoogleSheetModalOpen, setIsBuffetGoogleSheetModalOpen] = useState(false);
  const [tempGoogleSheetUrl, setTempGoogleSheetUrl] = useState('');

  // Admin emails definition
  const adminEmails = ['etegahanalysis@gmail.com', 'mohamed.gamal.work0@gmail.com'];

  // Helper to check if a value refers strictly to Admin
  const isAdminIdentifier = (val) => {
    if (!val) return false;
    const lower = String(val).toLowerCase().trim();
    if (lower === 'admin' || lower === 'الإدارة' || lower === 'ادارة' || lower === '👑 الإدارة' || lower === 'الرئيسي' || lower === 'حساب رئيسي') return true;
    if (adminEmails.includes(lower)) return true;
    if (lower === 'etegahanalysis' || lower.startsWith('etegahanalysis@') || lower.startsWith('mohamed.gamal.work0@')) return true;
    return false;
  };

  // Helper to sanitize display names so admin emails are never shown
  const sanitizeDisplayName = (nameOrEmail) => {
    if (!nameOrEmail) return 'الإدارة';
    if (isAdminIdentifier(nameOrEmail)) return 'الإدارة';
    const emp = employees.find(e => e.email?.toLowerCase() === String(nameOrEmail).toLowerCase() || e.uid === nameOrEmail);
    if (emp) return emp.username || emp.name;
    return nameOrEmail;
  };

  // Assignment Assigner Display & Role Helper
  const getAssignerDisplay = () => {
    if (isAdmin) return '👑 الإدارة';
    if (isCoordinator) return `📋 منسق الإدارة (${currentEmpUser?.username || currentEmpUser?.name || 'منسق'})`;
    if (isLeader) return `👑 ليدر الفريق (${currentEmpUser?.username || currentEmpUser?.name || 'ليدر'})`;
    return `👤 ${currentEmpUser?.username || currentEmpUser?.name || 'موظف'}`;
  };

  const getAssignerRole = () => {
    if (isAdmin) return 'admin';
    if (isCoordinator) return 'coordinator';
    if (isLeader) return 'leader';
    return 'agent';
  };

  // Helper to extract the assigner/distributor for any lead
  const getLeadAssignerDisplay = (customer) => {
    if (!customer) return null;
    let res = null;
    if (customer.assignedBy) res = customer.assignedBy;
    else if (customer.assignmentHistory && customer.assignmentHistory.length > 0) {
      const last = customer.assignmentHistory[customer.assignmentHistory.length - 1];
      if (last?.assignedBy) res = last.assignedBy;
    } else if (customer.addedBy) {
      if (isAdminIdentifier(customer.addedBy)) return '👑 الإدارة';
      res = customer.addedBy;
    }
    if (!res) return null;
    return String(res)
      .replace(/إضافة و(استيراد|رفع) داتا بواسطة\s*/g, '')
      .replace(/[()]/g, '')
      .trim();
  };

  // Helper to trace where a lead/phone number exists across all system cards/collections
  const getSystemLeadLocation = (phoneOrObj, currentDocId) => {
    if (!phoneOrObj) return [];
    const targetObj = typeof phoneOrObj === 'object' ? phoneOrObj : null;
    const rawPhone = targetObj ? (targetObj.phone || targetObj.phoneNumber || targetObj.id) : phoneOrObj;
    if (!rawPhone) return [];

    const normalizePhone = (ph) => {
      if (!ph) return '';
      let str = String(ph).replace(/[^0-9]/g, '');
      if (str.length > 10 && str.startsWith('20')) {
        str = str.substring(2);
      } else if (str.length > 10 && str.startsWith('0')) {
        str = str.substring(1);
      } else if (str.startsWith('0')) {
        str = str.substring(1);
      }
      return str;
    };

    const targetNorm = normalizePhone(rawPhone);
    if (!targetNorm || targetNorm.length < 7) return [];

    const getEmpName = (uidOrEmail) => {
      if (!uidOrEmail || uidOrEmail === 'admin' || uidOrEmail === 'الإدارة') return '👑 الإدارة';
      const emp = (employees || []).find(e => e.uid === uidOrEmail || e.email === uidOrEmail || e.username === uidOrEmail || e.name === uidOrEmail);
      if (emp) return emp.username || emp.name || emp.email;
      return uidOrEmail;
    };

    const locations = [];

    // 1. Check Leads CRM collection
    const crmMatch = (leadsCrm || []).find(item => item.id !== currentDocId && normalizePhone(item.phoneNumber || item.phone || item.id) === targetNorm);
    if (crmMatch) {
      const empName = getEmpName(crmMatch.assignedToUid || crmMatch.assignedTo);
      const statusLabel = CRM_STATUS_MAP[crmMatch.crmStatus]?.label || crmMatch.crmStatus || 'غير محدد';
      locations.push({
        type: 'crm',
        label: `🎯 Leads CRM (${empName})`,
        subLabel: `الحالة: ${statusLabel}`,
        bg: 'bg-blue-100 text-blue-900 border-blue-300',
        icon: '🎯'
      });
    }

    // 2. Check Employee Added Leads collection
    const empLeadMatch = (employeeLeads || []).find(item => item.id !== currentDocId && normalizePhone(item.phoneNumber || item.phone || item.id) === targetNorm);
    if (empLeadMatch) {
      const empName = getEmpName(empLeadMatch.assignedToUid || empLeadMatch.addedBy || empLeadMatch.assignedTo);
      const statusLabel = CRM_STATUS_MAP[empLeadMatch.crmStatus]?.label || empLeadMatch.crmStatus || 'غير محدد';
      locations.push({
        type: 'employee_leads',
        label: `👤 داتا موظفين (${empName})`,
        subLabel: `الحالة: ${statusLabel}`,
        bg: 'bg-emerald-100 text-emerald-900 border-emerald-300',
        icon: '👤'
      });
    }

    // 3. Check Subscribed / Paid / Manual Customers (بيانات_تسجيل_العملاء)
    const custMatch = (customers || []).find(item => item.id !== currentDocId && normalizePhone(item.phoneNumber || item.phone || item.id) === targetNorm);
    if (custMatch) {
      const empName = getEmpName(custMatch.assignedToUid || custMatch.assignedTo);
      if (custMatch.status === 'عميل مشترك' || custMatch.status === 'مشترك' || custMatch.isSubscribed) {
        locations.push({
          type: 'subscribed',
          label: `🎉 عميل مشترك Paid (${empName})`,
          bg: 'bg-amber-100 text-amber-900 border-amber-300',
          icon: '🎉'
        });
      } else if (
        custMatch.source === 'website' || 
        custMatch.source === 'website_otp' || 
        custMatch.source === 'موقع الويب (OTP)' || 
        custMatch.addedBy === 'website_otp' || 
        custMatch.isWebsiteLead || 
        (typeof phoneOrObj === 'object' && (phoneOrObj.source === 'موقع الويب (OTP)' || phoneOrObj.addedBy === 'website_otp' || phoneOrObj.isVisitorDoc || phoneOrObj.status === 'website_visitor')) ||
        (visitors || []).some(v => normalizePhone(v.phone || v.phoneNumber || v.id) === targetNorm)
      ) {
        locations.push({
          type: 'website_customer',
          label: `🌐 مسجّل عبر موقع الويب (OTP) (${empName})`,
          bg: 'bg-purple-100 text-purple-900 border-purple-300',
          icon: '🌐'
        });
      } else if (custMatch.source === 'manual') {
        locations.push({
          type: 'manual_customer',
          label: `✋ عميل مضاف يدوياً (${empName})`,
          bg: 'bg-orange-100 text-orange-900 border-orange-300',
          icon: '✋'
        });
      }
    }

    // 4. Check Website Visitors OTP collection
    const visitorMatch = (visitors || []).find(item => item.id !== currentDocId && normalizePhone(item.phone || item.phoneNumber || item.id) === targetNorm);
    if (visitorMatch) {
      const empName = getEmpName(visitorMatch.assignedToUid || visitorMatch.assignedTo);
      locations.push({
        type: 'visitor',
        label: `📱 زائر موقع OTP (${empName})`,
        bg: 'bg-indigo-100 text-indigo-900 border-indigo-300',
        icon: '📱'
      });
    }

    if (locations.length === 0) {
      const isWebsiteOtp = targetObj && (
        targetObj.source === 'موقع الويب (OTP)' || 
        targetObj.source === 'website_otp' || 
        targetObj.source === 'website' || 
        targetObj.addedBy === 'website_otp' || 
        targetObj.isVisitorDoc || 
        targetObj.status === 'website_visitor' ||
        (targetObj.source && String(targetObj.source).includes('OTP')) ||
        (targetObj.source && String(targetObj.source).includes('موقع'))
      );

      if (isWebsiteOtp) {
        locations.push({
          type: 'website_otp',
          label: '📦 موقع الويب (OTP)',
          bg: 'bg-purple-100 text-purple-900 border-purple-300',
          icon: '📦'
        });
      } else {
        locations.push({
          type: 'new',
          label: '🆕 زائر جديد (غير مكرر بالنظام)',
          bg: 'bg-emerald-50 text-emerald-800 border-emerald-200',
          icon: '🆕'
        });
      }
    }

    return locations;
  };

