  const handleDeleteSingleEmployee = async (emp) => {
    if (!isAdmin) {
      toast.error('صلاحية المسح والحذف محصورة بالإدارة العليا فقط 🔒');
      return;
    }
    const empDisplayName = emp.username || emp.name || emp.email;
    const isLeaderRole = emp.jobTitle === 'Leader' || emp.jobTitle === 'ليدر' || emp.role === 'leader';
    const isCoordinatorRole = emp.jobTitle === 'Coordinator' || emp.jobTitle === 'منسق' || emp.role === 'coordinator';
    const isCustomerServiceRole = emp.jobTitle === 'Customer Service' || emp.role === 'customer_service';

    const empRoleLabel = isLeaderRole ? 'الليدر' : (isCoordinatorRole ? 'المنسق' : (isCustomerServiceRole ? 'خدمة العملاء' : 'الموظف (Agent)'));

    if (!window.confirm(`هل أنت متأكد من مسح ${empRoleLabel} (${empDisplayName}) ونقله إلى سلة المهملات، وتحويل جميع داتاه تلقائياً بواسطة الإدارة؟`)) return;

    try {
      const empUid = emp.uid || emp.id;
      const empEmail = emp.email?.toLowerCase();
      const empLeaderUid = emp.leaderUid || emp.leaderId;

      // Only Agents with a leader transfer to their leader. Leaders, Coordinators, and CS transfer directly to Admin/الإدارة العليا.
      let targetLeader = null;
      if (!isLeaderRole && !isCoordinatorRole && !isCustomerServiceRole) {
        targetLeader = employees.find(e => 
          (e.jobTitle === 'Leader' || e.jobTitle === 'ليدر' || e.role === 'leader') &&
          e.role !== 'admin' &&
          ((empLeaderUid && (e.uid === empLeaderUid || e.id === empLeaderUid)) ||
           (emp.leaderEmail && e.email?.toLowerCase() === emp.leaderEmail.toLowerCase()) ||
           (emp.leaderName && (e.name === emp.leaderName || e.username === emp.leaderName)))
        );
      }

      const targetAssigneeUid = targetLeader ? targetLeader.uid : 'admin';
      const targetAssigneeEmail = targetLeader ? (targetLeader.email || targetLeader.name || 'الإدارة') : 'الإدارة';
      const targetAssigneeName = targetLeader ? (targetLeader.username || targetLeader.name || targetLeader.email) : '👑 الإدارة العليا';

      // Collect matching leads/customers across all collections
      const leadsCrmToTransfer = leadsCrm.filter(l => 
        (empUid && l.assignedToUid === empUid) ||
        (empEmail && l.assignedTo?.toLowerCase() === empEmail) ||
        (emp.name && l.assignedTo === emp.name) ||
        (emp.username && l.assignedTo === emp.username)
      );

      const empLeadsToTransfer = employeeLeads.filter(l => 
        (empUid && l.assignedToUid === empUid) ||
        (empEmail && l.assignedTo?.toLowerCase() === empEmail) ||
        (emp.name && l.assignedTo === emp.name) ||
        (emp.username && l.assignedTo === emp.username)
      );

      const customersToTransfer = customers.filter(l => 
        (empUid && l.assignedToUid === empUid) ||
        (empEmail && l.assignedTo?.toLowerCase() === empEmail) ||
        (emp.name && l.assignedTo === emp.name) ||
        (emp.username && l.assignedTo === emp.username)
      );

      const logObj = {
        from: `${empRoleLabel} (${empDisplayName})`,
        to: targetAssigneeName,
        assignedBy: '👑 الإدارة العليا (تحويل تلقائي عقب المسح)',
        date: new Date().toISOString(),
        reason: `نقل تلقائي لداتا ${empRoleLabel} المحذوف إلى ${targetLeader ? `الليدر (${targetAssigneeName})` : 'الإدارة العليا'} بواسطة الإدارة`
      };

      const updatePayload = {
        assignedToUid: targetAssigneeUid,
        assignedTo: targetAssigneeEmail,
        assignedBy: '👑 الإدارة العليا',
        assignedByRole: 'Admin',
        assignedByUid: 'admin',
        assignedAt: serverTimestamp(),
        assignmentHistory: arrayUnion(logObj)
      };

      // Batch update leads/customers in chunks of 400
      const allItemsToTransfer = [
        ...leadsCrmToTransfer.map(item => ({ col: 'leads_crm', id: item.id })),
        ...empLeadsToTransfer.map(item => ({ col: 'employee_leads', id: item.id })),
        ...customersToTransfer.map(item => ({ col: 'visitor_customers', id: item.id }))
      ];

      for (let i = 0; i < allItemsToTransfer.length; i += 400) {
        const chunk = allItemsToTransfer.slice(i, i + 400);
        const batch = writeBatch(db);
        chunk.forEach(item => {
          batch.update(doc(db, item.col, item.id), updatePayload);
        });
        await batch.commit().catch(err => console.error('Error committing transferred leads batch:', err));
      }

      // If a Leader was deleted, unassign their team members' leaderUid in Firestore
      if (isLeaderRole) {
        const teamMembersToUnassign = employees.filter(e => e.leaderUid === empUid || e.leaderUid === emp.id);
        if (teamMembersToUnassign.length > 0) {
          const teamBatch = writeBatch(db);
          teamMembersToUnassign.forEach(m => {
            teamBatch.update(doc(db, 'users', m.id), {
              leaderUid: null,
              leaderName: '',
              leaderEmail: '',
              updatedAt: serverTimestamp()
            });
          });
          await teamBatch.commit().catch(err => console.error('Error unassigning team members leader:', err));
        }
      }

      // Move employee to recycle_bin & delete from users collection
      await setDoc(doc(db, 'recycle_bin', emp.id), {
        ...emp,
        originalCollection: 'users',
        type: 'employee',
        deletedAt: serverTimestamp(),
        transferredDataTo: targetAssigneeName,
        transferredDataCount: allItemsToTransfer.length
      });
      await deleteDoc(doc(db, 'users', emp.id));

      toast.success(
        targetLeader
          ? `تم نقل ${empRoleLabel} لسلة المهملات، وتوليت الإدارة تحويل ${allItemsToTransfer.length} عميل إلى الليدر (${targetAssigneeName}) بنجاح 🎯`
          : `تم نقل ${empRoleLabel} لسلة المهملات، وتوليت الإدارة تحويل ${allItemsToTransfer.length} عميل إلى الإدارة العليا بنجاح 🎯`
      );
    } catch (e) {
      console.error('Error deleting employee and transferring data:', e);
      toast.error('حدث خطأ أثناء مسح الحساب ونقل بياناته');
    }
  };

  const handleRestore = async (item) => {
    if (!isAdmin) {
      toast.error('صلاحية استرجاع البيانات محصورة بالإدارة العليا فقط 🔒');
      return;
    }
    try {
      const { originalCollection, type, source, itemType, deletedAt, deletedBy, deletedAtFormatted, data, name, title, id, status, ...restData } = item;
      const targetCol = originalCollection || item.source || (type === 'saudi_recommendations' ? 'saudi_recommendations' : type === 'us_recommendations' ? 'us_recommendations' : type === 'employee' ? 'users' : type === 'visitor' ? 'visitor_customers' : type === 'email' ? 'internal_emails' : 'بيانات_تسجيل_العملاء');
      const restoreObj = data || restData;
      await setDoc(doc(db, targetCol, item.id), restoreObj);
      await deleteDoc(doc(db, 'recycle_bin', item.id));
      toast.success(`تم استرجاع (${item.title || item.name || item.subject || item.phoneNumber || 'العنصر'}) بنجاح 🔄`);
    } catch (e) {
      console.error(e);
      toast.error('حدث خطأ أثناء استرجاع العنصر');
    }
  };

  const handleDeleteForever = async (id) => {
    if (!isAdmin) {
      toast.error('صلاحية الحذف النهائي للأبد محصورة بالإدارة العليا فقط 🔒');
      return;
    }
    if(window.confirm('هل أنت متأكد من الحذف النهائي للأبد؟ لا يمكن التراجع عن هذا الإجراء.')) {
      try {
        const item = recycleBin.find(r => r.id === id);
        // Also guarantee deletion from original collection if it still existed!
        if (item?.originalCollection) {
          await deleteDoc(doc(db, item.originalCollection, id)).catch(() => {});
        }
        if (item?.type === 'visitor' || item?.originalCollection === 'visitor_customers') {
          await deleteDoc(doc(db, 'visitor_customers', id)).catch(() => {});
        }
        if (item?.type === 'customer' || item?.originalCollection === 'بيانات_تسجيل_العملاء') {
          await deleteDoc(doc(db, 'بيانات_تسجيل_العملاء', id)).catch(() => {});
        }
        await deleteDoc(doc(db, 'recycle_bin', id));
        toast.success('تم الحذف النهائي بنجاح');
      } catch (error) {
        console.error("Error deleting:", error);
        toast.error('حدث خطأ أثناء الحذف');
      }
    }
  };

  const toggleRecycleSelection = (id) => {
    setSelectedRecycleItems(prev => prev.includes(id) ? prev.filter(rId => rId !== id) : [...prev, id]);
  };
  const toggleAllRecycleItems = () => {
    const filteredItems = recycleBin.filter(item => {
      const isVisitorItem = item.type === 'visitor' || item.originalCollection === 'visitor_customers' || item.source?.includes('موقع') || item.source?.includes('OTP');
      return rbFilter === 'all' 
        ? true 
        : rbFilter === 'visitor' 
          ? isVisitorItem 
          : rbFilter === 'customer' 
            ? (item.type === 'customer' && !isVisitorItem) 
            : item.type === rbFilter;
    });
    if (selectedRecycleItems.length === filteredItems.length && filteredItems.length > 0) setSelectedRecycleItems([]);
    else setSelectedRecycleItems(filteredItems.map(i => i.id));
  };
  const restoreSelectedRecycleItems = async () => {
    if (!isAdmin && !hasPermission(currentEmpUser, 'canRestoreFromRecycleBin')) {
      toast.error('صلاحية الاسترجاع محصورة بالإدارة والمصرح لهم فقط 🔒');
      return;
    }
    if (selectedRecycleItems.length === 0) return;
    if (!window.confirm(`هل أنت متأكد من استرجاع ${selectedRecycleItems.length} عنصر؟`)) return;
    const idsToRestore = [...selectedRecycleItems];
    const count = idsToRestore.length;
    const toRestoreSet = new Set(idsToRestore);
    const itemsToRestore = recycleBin.filter(i => toRestoreSet.has(i.id));

    // 1. INSTANT ZERO-LATENCY OPTIMISTIC UI UPDATE (0ms)
    setRecycleBin(prev => prev.filter(i => !toRestoreSet.has(i.id)));
    setSelectedRecycleItems([]);
    toast.success(`تم استرجاع ${count} عنصر فوراً بنجاح 🔄✨`);

    // 2. PARALLEL BACKGROUND RESTORE
    (async () => {
      await Promise.all(itemsToRestore.map(item => handleRestore(item)));
    })().catch(err => {
      console.error('Error restoring recycle items in background:', err);
    });
  };

  const deleteSelectedRecycleItemsForever = async () => {
    if (!isAdmin && !hasPermission(currentEmpUser, 'canEmptyRecycleBin')) {
      toast.error('صلاحية الحذف النهائي محصورة بالإدارة العليا فقط 🔒');
      return;
    }
    if (selectedRecycleItems.length === 0) return;
    if (!window.confirm(`هل أنت متأكد من الحذف النهائي لـ ${selectedRecycleItems.length} عنصر للأبد؟ لا يمكن التراجع عن هذا الإجراء.`)) return;
    const idsToDelete = [...selectedRecycleItems];
    const count = idsToDelete.length;
    const toDeleteSet = new Set(idsToDelete);
    const itemsToDelete = recycleBin.filter(r => toDeleteSet.has(r.id));

    // 1. INSTANT ZERO-LATENCY OPTIMISTIC UI UPDATE (0ms)
    setRecycleBin(prev => prev.filter(r => !toDeleteSet.has(r.id)));
    setSelectedRecycleItems([]);
    toast.success(`تم مسح ${count} عنصر نهائياً للأبد في نفس اللحظة 🗑️✨`);

    // 2. PARALLEL WRITEBATCH IN BACKGROUND
    (async () => {
      const BATCH_SIZE = 400;
      for (let i = 0; i < idsToDelete.length; i += BATCH_SIZE) {
        const chunk = idsToDelete.slice(i, i + BATCH_SIZE);
        const batch = writeBatch(db);
        for (const id of chunk) {
          batch.delete(doc(db, 'recycle_bin', id));
        }
        await batch.commit();
      }
      // Also cleanup original collections in parallel if any
      await Promise.all(itemsToDelete.map(async (item) => {
        try {
          if (item?.originalCollection) {
            await deleteDoc(doc(db, item.originalCollection, item.id));
          }
        } catch (_) {}
      }));
    })().catch(err => {
      console.error('Error in permanent delete:', err);
    });
  };

  const handleAssignCustomer = async (chatId, empUid) => {
    if (!empUid) return;
    try {
      const customer = customers.find(c => c.id === chatId);
      const prevEmpName = employees.find(e => e.uid === customer?.assignedToUid || e.email === customer?.assignedTo)?.username || employees.find(e => e.uid === customer?.assignedToUid || e.email === customer?.assignedTo)?.name || (customer?.assignedTo === 'admin' || customer?.assignedTo === 'الإدارة' ? '👑 الإدارة' : '👑 الإدارة');
      const assignerDisplay = getAssignerDisplay();
      const assignerRole = getAssignerRole();
      const assignerUid = isAdmin ? 'admin' : (currentUser?.uid || '');

      if (empUid === 'admin') {
        const logObj = createAssignmentLog(prevEmpName, '👑 الإدارة', assignerDisplay);
        await updateDoc(doc(db, 'بيانات_تسجيل_العملاء', chatId), {
          status: 'unassigned',
          assignedTo: 'admin',
          assignedToUid: 'admin',
          assignedBy: assignerDisplay,
          assignedByRole: assignerRole,
          assignedByUid: assignerUid,
          assignedAt: serverTimestamp(),
          updatedAt: serverTimestamp(),
          assignmentHistory: arrayUnion(logObj),
          unread: 1
        });
        toast.success('تم إرجاع العميل إلى الإدارة 👑');
      } else {
        const emp = employees.find(e => e.uid === empUid);
        if (!emp) return;
        const targetEmpName = emp.role === 'admin' ? `👑 الإدارة (${emp.username || emp.name})` : `👤 ${emp.username || emp.name}`;
        const logObj = createAssignmentLog(prevEmpName, targetEmpName, assignerDisplay);

        // 1. Update customer in 'بيانات_تسجيل_العملاء'
        await updateDoc(doc(db, 'بيانات_تسجيل_العملاء', chatId), {
          status: 'assigned',
          assignedTo: emp.email,
          assignedToUid: emp.uid,
          assignedBy: assignerDisplay,
          assignedByRole: assignerRole,
          assignedByUid: assignerUid,
          assignedAt: serverTimestamp(),
          updatedAt: serverTimestamp(),
          assignmentHistory: arrayUnion(logObj),
          unread: 1
        });

        // 2. Transfer customer directly to 'leads_crm' collection so it appears on Employee/Leader Leads CRM dashboard table!
        const cleanPhone = (customer?.phoneNumber || '').replace(/[^0-9+]/g, '');
        const crmDocId = cleanPhone ? cleanPhone.replace(/[^0-9]/g, '') : chatId;

        await setDoc(doc(db, 'leads_crm', crmDocId), {
          name: customer?.name || 'عميل محول من واتساب',
          phoneNumber: cleanPhone.startsWith('+') ? cleanPhone : `+${cleanPhone}`,
          source: customer?.source || 'واتساب الموقع',
          assignedTo: emp.email,
          assignedToUid: emp.uid,
          assignedBy: assignerDisplay,
          assignedByRole: assignerRole,
          assignedByUid: assignerUid,
          crmStatus: 'unassigned', // Initial state in waiting
          status: 'assigned',
          assignedAt: serverTimestamp(),
          createdAt: customer?.createdAt || serverTimestamp(),
          updatedAt: serverTimestamp(),
          notes: customer?.notes || '',
          notesHistory: customer?.notesHistory || [],
          assignmentHistory: arrayUnion(logObj)
        }, { merge: true });

        toast.success(`تم تحويل العميل إلى Leads CRM الخاص بـ ${emp.username || emp.name} على الداش بورد 🎯`);
      }
    } catch (error) {
      console.error("خطأ في إسناد المحادثة:", error);
      toast.error('حدث خطأ أثناء تحويل العميل');
    }
  };

