  const handleSaveSubscriptionDetails = async (e) => {
    e?.preventDefault();
    if (!selectedSubCustomer) return;

    // Strict Required Fields Validation
    if (!subServiceType) {
      toast.error('يرجى اختيار نوع الباقة (حقل إجباري) ⚠️');
      return;
    }
    if (!subServiceCategory) {
      toast.error('يرجى اختيار تصنيف الخدمة (حقل إجباري) ⚠️');
      return;
    }
    if (!subPaymentType) {
      toast.error('يرجى اختيار نوع الدفع (حقل إجباري) ⚠️');
      return;
    }
    if (!subReceiptDate) {
      toast.error('يرجى تحديد تاريخ الإشعار / التحويل (حقل إجباري) ⚠️');
      return;
    }
    if (!subStartDate) {
      toast.error('يرجى تحديد تاريخ بداية الخدمة (حقل إجباري) ⚠️');
      return;
    }
    const isPercentage = (subServiceType === 'اتفاق نسبة' || subPaymentType === 'percentage');
    if (!isPercentage && !subEndDate) {
      toast.error('يرجى تحديد تاريخ نهاية الخدمة (إجباري للباقات) ⚠️');
      return;
    }
    if (isPercentage && !subAgreedPercentage?.trim()) {
      toast.error('يرجى إدخال النسبة المتفق عليها (حقل إجباري) ⚠️');
      return;
    }
    const cleanPaid = (subPaidAmount || '').replace(/[^0-9.]/g, '');
    if (!cleanPaid || parseFloat(cleanPaid) <= 0) {
      toast.error('يرجى إدخال المبلغ المدفوع (حقل إجباري) ⚠️');
      return;
    }
    if (subPaymentType === 'partial') {
      const cleanRem = (subRemainingAmount || '').replace(/[^0-9.]/g, '');
      if (!cleanRem) {
        toast.error('يرجى إدخال المبلغ المتبقي (إجباري لنظام الجزء وباقي جزء) ⚠️');
        return;
      }
    }
    if (!subReceiptFileUrl) {
      toast.error('يرجى إرفاق صورة أو ملف إشعار التحويل (حقل إجباري) ⚠️');
      return;
    }

    setSubSaving(true);
    try {
      const now = new Date();
      const uploadIso = now.toISOString();
      const dateFormatted = now.toLocaleDateString('ar-EG', { year: 'numeric', month: '2-digit', day: '2-digit' });
      const timeFormatted = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
      const currentMonthKey = (subReceiptDate || subStartDate || uploadIso.slice(0, 10)).slice(0, 7);
      const existingHistory = selectedSubCustomer.subscriptionHistory || [];
      let updatedHistory = [];

      if (editingReceiptId) {
        // Editing existing payment record
        const editorIdentity = isAdmin 
          ? '👑 الإدارة' 
          : (currentEmpUser?.jobTitle === 'Customer Service' || currentEmpUser?.role === 'customer_service')
            ? `${currentEmpUser?.name || 'موظف'} (خدمة عملاء)`
            : `${currentEmpUser?.name || currentUser?.email?.split('@')[0] || 'موظف'} (${currentEmpUser?.jobTitle || currentEmpUser?.role || 'موظف'})`;

        updatedHistory = existingHistory.map(h => {
          if (h.id === editingReceiptId) {
            return {
              ...h,
              serviceType: subServiceType || h.serviceType,
              packageType: subServiceType || h.packageType,
              serviceCategory: subServiceCategory || h.serviceCategory,
              paymentType: subPaymentType,
              agreedPercentage: isPercentage ? subAgreedPercentage : '',
              receiptDate: subReceiptDate || h.receiptDate || h.date,
              date: subReceiptDate || subStartDate,
              month: currentMonthKey,
              startDate: subStartDate,
              endDate: isPercentage ? '' : subEndDate,
              paidAmount: cleanPaid,
              remainingAmount: subPaymentType === 'partial' ? (subRemainingAmount || '').replace(/[^0-9.]/g, '') : '',
              receiptProof: subReceiptProof?.trim() || h.receiptProof || 'مسجل',
              receiptUrl: subReceiptFileUrl || '',
              notes: subNotes?.trim() || '',
              lastEditedBy: editorIdentity,
              lastEditedByUid: currentUser?.uid || (isAdmin ? 'admin' : ''),
              lastEditedAt: uploadIso,
              lastEditedDateTime: `${dateFormatted} • ${timeFormatted}`,
              isEdited: true
            };
          }
          return h;
        });
      } else {
        // Adding new payment record
        const uploadedDateTimeLabel = `${dateFormatted} • ${timeFormatted}`;
        const newPaymentRecord = {
          id: 'rec_' + Date.now(),
          receiptDate: subReceiptDate,
          date: subReceiptDate || subStartDate || uploadIso.slice(0, 10),
          month: currentMonthKey,
          uploadedAt: uploadIso,
          uploadedDateTime: uploadedDateTimeLabel,
          startDate: subStartDate,
          endDate: isPercentage ? '' : subEndDate,
          serviceType: subServiceType || 'باقة سنوية',
          serviceCategory: subServiceCategory || 'توصيات سعودي',
          packageType: subServiceType || 'باقة سنوية',
          paymentType: subPaymentType,
          agreedPercentage: isPercentage ? subAgreedPercentage : '',
          paidAmount: cleanPaid,
          remainingAmount: subPaymentType === 'partial' ? (subRemainingAmount || '').replace(/[^0-9.]/g, '') : '',
          receiptProof: subReceiptProof?.trim() || 'مسجل',
          receiptUrl: subReceiptFileUrl || '',
          notes: subNotes?.trim() || '',
          savedBy: currentEmpUser?.name || currentUser?.email || 'الإدارة',
          savedByUid: currentUser?.uid || 'admin',
          savedAt: uploadIso
        };
        updatedHistory = [newPaymentRecord, ...existingHistory];
      }

      // Primary subscription details synced from latest history record
      const primaryRec = updatedHistory[0] || {};
      const subData = {
        startDate: primaryRec.startDate || subStartDate,
        endDate: isPercentage ? '' : (primaryRec.endDate || subEndDate),
        serviceType: primaryRec.serviceType || subServiceType || 'باقة سنوية',
        serviceCategory: primaryRec.serviceCategory || subServiceCategory || 'توصيات سعودي',
        paymentType: primaryRec.paymentType || subPaymentType,
        agreedPercentage: isPercentage ? subAgreedPercentage : '',
        paidAmount: primaryRec.paidAmount || cleanPaid,
        remainingAmount: primaryRec.paymentType === 'partial' ? primaryRec.remainingAmount : '',
        receiptProof: primaryRec.receiptProof || (subReceiptProof?.trim() || 'مسجل'),
        receiptUrl: primaryRec.receiptUrl || subReceiptFileUrl || '',
        notes: primaryRec.notes || subNotes?.trim() || '',
        month: primaryRec.month || currentMonthKey,
        savedBy: currentEmpUser?.name || currentUser?.email || 'الإدارة',
        savedByUid: currentUser?.uid || 'admin',
        savedAt: uploadIso
      };

      const targetId = selectedSubCustomer.id;
      const cleanPhone = (selectedSubCustomer.phoneNumber || '').replace(/[^0-9+]/g, '');
      const phoneDocId = cleanPhone ? cleanPhone.replace(/[^0-9]/g, '') : targetId;

      const promises = [
        updateDoc(doc(db, 'leads_crm', targetId), { subscriptionDetails: subData, subscriptionHistory: updatedHistory, crmStatus: 'subscribed', updatedAt: serverTimestamp() }).catch(() => {}),
        updateDoc(doc(db, 'employee_leads', targetId), { subscriptionDetails: subData, subscriptionHistory: updatedHistory, crmStatus: 'subscribed', updatedAt: serverTimestamp() }).catch(() => {}),
      ];
      if (phoneDocId) {
        promises.push(updateDoc(doc(db, 'بيانات_تسجيل_العملاء', phoneDocId), { subscriptionDetails: subData, subscriptionHistory: updatedHistory, crmStatus: 'subscribed', updatedAt: serverTimestamp() }).catch(() => {}));
      }
      await Promise.all(promises);

      // Clear all input fields so the form is clean and empty
      setSubReceiptDate('');
      setSubStartDate('');
      setSubEndDate('');
      setSubServiceType('');
      setSubServiceCategory('');
      setSubPaymentType('');
      setSubAgreedPercentage('');
      setSubPaidAmount('');
      setSubRemainingAmount('');
      setSubReceiptProof('');
      setSubReceiptFileUrl('');
      setSubNotes('');
      setEditingReceiptId(null);
      setIsAddingNewReceipt(false);

      // Update state
      setSubPaymentHistory(updatedHistory);
      setSelectedSubCustomer(prev => ({ ...prev, subscriptionDetails: subData, subscriptionHistory: updatedHistory }));

      // Close modal immediately upon saving
      setIsSubscriptionModalOpen(false);

      toast.success(editingReceiptId ? 'تم حفظ التعديلات وإغلاق النافذة بنجاح 💾✨' : 'تم حفظ بيانات الاشتراك وإغلاق النافذة بنجاح 💾✨');
    } catch (err) {
      console.error('Error saving subscription details:', err);
      toast.error('حدث خطأ أثناء حفظ بيانات الاشتراك');
    } finally {
      setSubSaving(false);
    }
  };

  // --- SAUDI & US MARKET RECOMMENDATIONS HELPERS & HANDLERS (v2.23) ---
  const calculateSaudiPercentage = (signal) => {
    const sup1 = parseFloat(String(signal.support1 || '').replace(/[^0-9.]/g, ''));
    if (!sup1 || isNaN(sup1) || sup1 <= 0) return null;

    if (signal.status === 'target1') {
      const res1 = parseFloat(String(signal.resistance1 || '').replace(/[^0-9.]/g, ''));
      if (!isNaN(res1)) return ((res1 - sup1) / sup1) * 100;
    } else if (signal.status === 'target2') {
      const res2 = parseFloat(String(signal.resistance2 || '').replace(/[^0-9.]/g, ''));
      if (!isNaN(res2)) return ((res2 - sup1) / sup1) * 100;
    } else if (signal.status === 'target3') {
      const res3 = parseFloat(String(signal.resistance3 || '').replace(/[^0-9.]/g, ''));
      if (!isNaN(res3)) return ((res3 - sup1) / sup1) * 100;
    } else if (signal.status === 'target4') {
      const res4 = parseFloat(String(signal.resistance4 || '').replace(/[^0-9.]/g, ''));
      if (!isNaN(res4)) return ((res4 - sup1) / sup1) * 100;
    } else if (signal.status === 'stop_loss') {
      const sl = parseFloat(String(signal.stopLoss || '').replace(/[^0-9.]/g, ''));
      if (!isNaN(sl)) return ((sl - sup1) / sup1) * 100;
    }
    return null;
  };

  const calculateSaudiGainValue = (signal) => {
    const sup1 = parseFloat(String(signal.support1 || '').replace(/[^0-9.]/g, ''));
    if (!sup1 || isNaN(sup1) || sup1 <= 0) return null;

    let exitPrice = null;
    if (signal.status === 'target1') {
      exitPrice = parseFloat(String(signal.resistance1 || '').replace(/[^0-9.]/g, ''));
    } else if (signal.status === 'target2') {
      exitPrice = parseFloat(String(signal.resistance2 || '').replace(/[^0-9.]/g, ''));
    } else if (signal.status === 'target3') {
      exitPrice = parseFloat(String(signal.resistance3 || '').replace(/[^0-9.]/g, ''));
    } else if (signal.status === 'target4') {
      exitPrice = parseFloat(String(signal.resistance4 || '').replace(/[^0-9.]/g, ''));
    } else if (signal.status === 'stop_loss') {
      exitPrice = parseFloat(String(signal.stopLoss || '').replace(/[^0-9.]/g, ''));
    }

    if (exitPrice !== null && !isNaN(exitPrice)) {
      return exitPrice - sup1;
    }
    return null;
  };

  const calculateUsGainValue = (signal) => {
    const buyMatch = String(signal.buyPrice || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
    const buy = buyMatch ? parseFloat(buyMatch[0]) : NaN;
    if (!buy || isNaN(buy) || buy <= 0) return null;

    let exitPrice = null;
    if (signal.status === 'target1') {
      const t1Match = String(signal.target1 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      exitPrice = t1Match ? parseFloat(t1Match[0]) : NaN;
    } else if (signal.status === 'target2') {
      const t2Match = String(signal.target2 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      exitPrice = t2Match ? parseFloat(t2Match[0]) : NaN;
      } else if (signal.status === 'target3') {
        const t3Match = String(signal.target3 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
        exitPrice = t3Match ? parseFloat(t3Match[0]) : NaN;
      } else if (signal.status === 'target4') {
        const t4Match = String(signal.target4 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
        exitPrice = t4Match ? parseFloat(t4Match[0]) : NaN;
    } else if (signal.status === 'stop_loss') {
      const slMatch = String(signal.stopLoss || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      exitPrice = slMatch ? parseFloat(slMatch[0]) : NaN;
    }

    if (exitPrice !== null && !isNaN(exitPrice)) {
      return exitPrice - buy;
    }
    return null;
  };

  const calculateUsPercentage = (signal) => {
    const buyMatch = String(signal.buyPrice || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
    const buy = buyMatch ? parseFloat(buyMatch[0]) : NaN;
    if (!buy || isNaN(buy) || buy <= 0) return null;

    if (signal.status === 'target1') {
      const t1Match = String(signal.target1 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      const t1 = t1Match ? parseFloat(t1Match[0]) : NaN;
      if (!isNaN(t1)) return ((t1 - buy) / buy) * 100;
    } else if (signal.status === 'target2') {
      const t2Match = String(signal.target2 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      const t2 = t2Match ? parseFloat(t2Match[0]) : NaN;
      if (!isNaN(t2)) return ((t2 - buy) / buy) * 100;
      } else if (signal.status === 'target3') {
        const t3Match = String(signal.target3 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
        const t3 = t3Match ? parseFloat(t3Match[0]) : NaN;
        if (!isNaN(t3)) return ((t3 - buy) / buy) * 100;
      } else if (signal.status === 'target4') {
        const t4Match = String(signal.target4 || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
        const t4 = t4Match ? parseFloat(t4Match[0]) : NaN;
        if (!isNaN(t4)) return ((t4 - buy) / buy) * 100;
    } else if (signal.status === 'stop_loss') {
      const slMatch = String(signal.stopLoss || '').replace(/,/g, '.').match(/\d+(?:\.\d+)?/);
      const sl = slMatch ? parseFloat(slMatch[0]) : NaN;
      if (!isNaN(sl)) return ((sl - buy) / buy) * 100;
    }
    return null;
  };


  // High-performance Canvas Image Compressor (Reduces 5MB+ base64 screenshots to ~50KB in 50ms)
  const compressImageDataUrl = (dataUrl, maxWidth = 900, maxHeight = 900, quality = 0.65) => {
    return new Promise((resolve) => {
      if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image')) {
        resolve(dataUrl || '');
        return;
      }
      // If already small base64, skip canvas overhead
      if (dataUrl.length < 100000) {
        resolve(dataUrl);
        return;
      }
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxWidth || height > maxHeight) {
          if (width > height) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          } else {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        const compressed = canvas.toDataURL('image/jpeg', quality);
        resolve(compressed);
      };
      img.onerror = () => resolve(dataUrl);
      img.src = dataUrl;
    });
  };

  const performOcrOnImage = async (imageSrc) => {
    try {
      if (!window.Tesseract) {
        await new Promise((resolve, reject) => {
          const script = document.createElement('script');
          script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
          script.onload = resolve;
          script.onerror = reject;
          document.head.appendChild(script);
        });
      }
      if (window.Tesseract) {
        const result = await window.Tesseract.recognize(imageSrc, 'ara+eng');
        return result?.data?.text || '';
      }
    } catch (err) {
      console.error('OCR Error:', err);
    }
    return '';
  };

  // Helper to sanitize numeric entries and strip lone dots or invalid values
  // Helper to sanitize numeric entries and strip lone dots or invalid values
  const cleanNum = (val) => {
    if (val === undefined || val === null) return '';
    let str = String(val).trim();
    if (!str || str === '.' || str === '-' || str === '—' || str === 'null' || str === 'undefined') return '';
    // Normalize Arabic numbers & European decimal commas (e.g. 1,70 -> 1.70)
    str = str.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/٫/g, '.').replace(/(\d+),(\d+)/g, '$1.$2');
    if (str.endsWith('.')) str = str.slice(0, -1);
    if (!isNaN(Number(str))) return str;
    // Allow ranges or formatted numbers containing digits like "1.70 ~ 2.10"
    if (/\d+(?:\.\d+)?/.test(str)) {
      return str;
    }
    return '';
  };

  const parseSaudiWhatsAppText = (text) => {
    if (!text) return {};
    let norm = String(text).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/٫/g, '.');
    const res = {};
    
    // 1. Stock Code
    const codeMatch = norm.match(/الرمز\s*\(?(\d{4})\)?/i) || 
                      norm.match(/كود\s*\(?(\d{4})\)?/i) || 
                      norm.match(/\((\d{4})\)/) || 
                      norm.match(/\b(\d{4})\b/);
    if (codeMatch) {
      res.stockCode = codeMatch[1].trim();
    }

    // 2. Stock Name
    const nameCodeMatch = norm.match(/([^\n\d\(\)]+)\s*\((\d{4})\)/) || norm.match(/\(?(\d{4})\)?\s*([^\n\d\(\)]+)/);
    if (nameCodeMatch) {
      const candidate = nameCodeMatch[1].trim();
      if (/^\d{4}$/.test(candidate)) {
        res.stockName = nameCodeMatch[2].trim();
      } else {
        res.stockName = candidate;
      }
    } else {
      const nameMatch = norm.match(/سهم\s*([^\n\d\(\)]+)/i) || norm.match(/اسم\s*السهم\s*[:=]?\s*([^\n\d\(\)]+)/i);
      if (nameMatch) res.stockName = nameMatch[1].trim();
    }

    if (res.stockCode && (!res.stockName || res.stockName === 'الرمز')) {
      const knownSaudiStocks = {
        '1120': 'الراجحي',
        '2222': 'أرامكو',
        '1180': 'الأهلي',
        '2010': 'سابك',
        '7010': 'إس تي سي',
        '4327': 'الأهلي ريت 1'
      };
      if (knownSaudiStocks[res.stockCode]) {
        res.stockName = knownSaudiStocks[res.stockCode];
      }
    }

    // 3. Supports
    const sup1Match = norm.match(/(?:دعم\s*1\b|دعم\s*أول|الدعم\s*الأول|الدعم|دعم|دخول|سعر\s*الدخول|سعر\s*الشراء|شراء|نقطة\s*الشراء|Buy(?:\s*at)?)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (sup1Match) res.support1 = cleanNum(sup1Match[1]);

    const sup2Match = norm.match(/(?:دعم\s*2\b|دعم\s*ثان[يى]|الدعم\s*الثاني)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (sup2Match) res.support2 = cleanNum(sup2Match[1]);

    // 4. Resistances / Targets
    const res1Match = norm.match(/(?:مقاومة\s*1\b|مقاومة\s*أول[ىي]|المقاومة\s*الأولى|هدف\s*1\b|الهدف\s*الأول|الهدف\s*1\b|Target\s*1\b|T1\b)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (res1Match) res.resistance1 = cleanNum(res1Match[1]);

    const res2Match = norm.match(/(?:مقاومة\s*2\b|مقاومة\s*ثاني[ةه]|المقاومة\s*الثانية|هدف\s*2\b|الهدف\s*الثاني|الهدف\s*2\b|Target\s*2\b|T2\b)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (res2Match) res.resistance2 = cleanNum(res2Match[1]);

    const res3Match = norm.match(/(?:مقاومة\s*3\b|مقاومة\s*ثالث[ةه]|المقاومة\s*الثالثة|هدف\s*3\b|الهدف\s*الثالث|الهدف\s*3\b|Target\s*3\b|T3\b)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (res3Match) res.resistance3 = cleanNum(res3Match[1]);

    const res4Match = norm.match(/(?:مقاومة\s*4\b|مقاومة\s*رابع[ةه]|المقاومة\s*الرابعة|هدف\s*4\b|الهدف\s*الرابع|الهدف\s*4\b|Target\s*4\b|T4\b)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (res4Match) res.resistance4 = cleanNum(res4Match[1]);

    // Check targets list match
    const targetsListMatch = norm.match(/(?:الأهداف|الاهداف|أهداف|اهداف|المقاومات|مقاومات|Targets|Target)\s*[:=]?\s*([0-9\.\s\,\-\/]+)/i);
    if (targetsListMatch) {
      const numbers = targetsListMatch[1].match(/\d+(?:\.\d+)?/g);
      if (numbers && numbers.length > 0) {
        if (!res.resistance1 && numbers[0]) res.resistance1 = cleanNum(numbers[0]);
        if (!res.resistance2 && numbers[1]) res.resistance2 = cleanNum(numbers[1]);
        if (!res.resistance3 && numbers[2]) res.resistance3 = cleanNum(numbers[2]);
        if (!res.resistance4 && numbers[3]) res.resistance4 = cleanNum(numbers[3]);
      }
    }

    // 5. Stop Loss
    const slMatch = norm.match(/(?:كسر\s*الدعم\s*تحت|إيقاف\s*الخسارة|وقف\s*الخسارة|الوقف|وقف|Stop\s*Loss|SL)\s*[:=≈]?\s*\(?(\d+(?:\.\d+)?)\)?/i);
    if (slMatch) res.stopLoss = cleanNum(slMatch[1]);

    return res;
  };

  const parseUsWhatsAppText = (text) => {
    if (!text) return {};
    let norm = String(text).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/٫/g, '.');
    // Replace European commas between digits e.g. 1,70 -> 1.70 or 2,90 -> 2.90
    norm = norm.replace(/(\d+),(\d+)/g, '$1.$2');

    const res = {};

    // Check for Options contract parameters (CALL / PUT / Strike / Expiration)
    const callPutMatch = norm.match(/\b(CALL|PUT)\b/i);
    const strikeMatch = norm.match(/(?:St|ST|Strike|إسترايك|استرايك|سترايك)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    const expiryMatch = norm.match(/\b(\d{2}[-/.]\d{2}[-/.]\d{4}|\d{4}[-/.]\d{2}[-/.]\d{2})\b/);

    if (callPutMatch || strikeMatch || expiryMatch) {
      res.marketType = 'options';
      const optType = callPutMatch ? callPutMatch[1].toUpperCase() : '';
      const strikeVal = strikeMatch ? strikeMatch[1] : '';
      const expiryVal = expiryMatch ? expiryMatch[1] : '';

      const notesParts = [];
      if (optType) notesParts.push(optType);
      if (strikeVal) notesParts.push(`ST ${strikeVal}`);
      if (expiryVal) notesParts.push(`Exp: ${expiryVal}`);

      if (notesParts.length > 0) {
        res.notes = notesParts.join(' • ');
      }
    }

    // Reserved non-symbol words
    const reservedWords = new Set(['BUY', 'SELL', 'T', 'T1', 'T2', 'SL', 'STOP', 'TARGET', 'CALL', 'PUT', 'ST', 'STRIKE', 'EXP', 'EXPIRY', 'ENTRY']);

    // Symbol extraction
    const symMatch = norm.match(/رمز\s*[:=]?\s*([A-Z]{1,5})/i) || norm.match(/Symbol\s*[:=]?\s*([A-Z]{1,5})/i);
    if (symMatch) {
      res.symbol = symMatch[1].toUpperCase();
    } else {
      const lines = norm.split('\n').map(l => l.trim()).filter(Boolean);
      for (const line of lines) {
        const cleanLine = line.toUpperCase().trim();
        if (/^[A-Z]{1,5}$/.test(cleanLine) && !reservedWords.has(cleanLine)) {
          res.symbol = cleanLine;
          break;
        }
      }
      if (!res.symbol) {
        const words = norm.match(/\b([A-Z]{1,5})\b/g);
        if (words) {
          for (const w of words) {
            const wUpper = w.toUpperCase();
            if (!reservedWords.has(wUpper)) {
              res.symbol = wUpper;
              break;
            }
          }
        }
      }
    }

    // Buy Price / Entry
    const buyMatch = norm.match(/(?:Buy\s*at|Buy|Entry|دخول|شراء|سعر\s*الدخول|سعر\s*الشراء|دعم|@)\s*[:=≈]?\s*([\d\.\s\~\-]+)/i);
    if (buyMatch) {
      let rawBuy = buyMatch[1].trim();
      rawBuy = rawBuy.replace(/[^\d\.\s\~\-]/g, '').trim();
      res.buyPrice = cleanNum(rawBuy);
    }

    // Target 1 (Supports T1, T, Target 1, Goal 1, الهدف الأول)
    const t1Match = norm.match(/(?:\bT1[\.\:]?|\bT[\.\:]?|Target\s*1[\.\:]?|Goal\s*1[\.\:]?|الهدف\s*1[\.\:]?|هدف\s*1[\.\:]?|الهدف\s*الأول)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (t1Match) res.target1 = cleanNum(t1Match[1]);

    // Target 2
    const t2Match = norm.match(/(?:\bT2[\.\:]?|Target\s*2[\.\:]?|Goal\s*2[\.\:]?|الهدف\s*2[\.\:]?|هدف\s*2[\.\:]?|الهدف\s*الثاني)\s*[:=≈]?\s*(\d+(?:\.\d+)?)/i);
    if (t2Match) res.target2 = cleanNum(t2Match[1]);

    // Fallback: Targets list match
    if (!res.target1 || !res.target2) {
      const targetsListMatch = norm.match(/(?:Targets|Target|Goals|Goal|الأهداف|الاهداف|أهداف|اهداف)\s*[:=]?\s*([0-9\.\s\,\-\/]+)/i);
      if (targetsListMatch) {
        const numbers = targetsListMatch[1].match(/\d+(?:\.\d+)?/g);
        if (numbers && numbers.length > 0) {
          if (!res.target1 && numbers[0]) res.target1 = cleanNum(numbers[0]);
          if (!res.target2 && numbers[1]) res.target2 = cleanNum(numbers[1]);
        }
      }
    }

    // Stop Loss
    const slMatch = norm.match(/(?:\bSL[\.\:]?|Stop\s*Loss[\.\:]?|\bStop[\.\:]?|إيقاف\s*الخسارة|وقف\s*الخسارة|الوقف|وقف)\s*[:=≈]?\s*\(?(\d+(?:\.\d+)?)\)?/i);
    if (slMatch) res.stopLoss = cleanNum(slMatch[1]);

    return res;
  };

  const handleSaudiTextChange = (text) => {
    setSaudiRawTextPaste(text);
    if (text.trim()) {
      const parsed = parseSaudiWhatsAppText(text);
      if (parsed.stockName) setSaudiStockName(parsed.stockName);
      if (parsed.stockCode) setSaudiStockCode(parsed.stockCode);
      if (parsed.support1) setSaudiSupport1(parsed.support1);
      if (parsed.support2) setSaudiSupport2(parsed.support2);
      if (parsed.resistance1) setSaudiResistance1(parsed.resistance1);
      if (parsed.resistance2) setSaudiResistance2(parsed.resistance2);
      if (parsed.resistance3) setSaudiResistance3(parsed.resistance3);
      if (parsed.resistance4) setSaudiResistance4(parsed.resistance4);
      if (parsed.stopLoss) setSaudiStopLoss(parsed.stopLoss);
    }
  };

  const handleUsTextChange = (text) => {
    setUsRawTextPaste(text);
    if (text.trim()) {
      const parsed = parseUsWhatsAppText(text);
      if (parsed.symbol) setUsSymbol(parsed.symbol);
      if (parsed.buyPrice) setUsBuyPrice(parsed.buyPrice);
      if (parsed.target1) setUsTarget1(parsed.target1);
      if (parsed.target2) setUsTarget2(parsed.target2);
      if (parsed.stopLoss) setUsStopLoss(parsed.stopLoss);
      if (parsed.marketType) setUsMarketType(parsed.marketType);
      if (parsed.notes) setUsNotes(parsed.notes);
    }
  };

