  const handleSavePayroll = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!editingPayrollEmp) return;

    const empDocId = editingPayrollEmp.id;
    const empUid = editingPayrollEmp.uid;
    const empKeys = Array.from(new Set([empDocId, empUid].filter(Boolean)));

    const now = new Date();
    const formattedNow = now.toLocaleDateString('ar-EG') + ' • ' + now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
    const userRole = isAdmin ? '👑 الإدارة' : isCoordinator ? `📋 منسق الإدارة (${currentEmpUser?.name || 'منسق'})` : (currentEmpUser?.name || 'موظف');

    const base = parseFloat(payrollBaseSalary) || 0;
    const adv = parseFloat(payrollAdvances) || 0;
    const kpi = parseFloat(payrollKpiDeduction) || 0;
    const lateD = parseFloat(payrollLateDeduction) || 0;
    const net = Math.max(0, base - adv - kpi - lateD);

    const docData = {
      empId: empDocId || empUid,
      empUid: empUid || empDocId,
      empName: editingPayrollEmp.username || editingPayrollEmp.name,
      jobTitle: editingPayrollEmp.jobTitle || editingPayrollEmp.role || 'موظف',
      baseSalary: payrollBaseSalary,
      advances: payrollAdvances,
      kpiDeduction: payrollKpiDeduction,
      lateDays: payrollLateDays,
      lateDeduction: payrollLateDeduction,
      checkIn: payrollCheckIn,
      checkOut: payrollCheckOut,
      netSalary: net,
      notes: payrollNotes,
      cycle: selectedPayrollCycle,
      updatedAt: serverTimestamp(),
      updatedBy: userRole,
      updatedDateTime: formattedNow
    };

    // Update local state and localStorage ONLY for cycle-specific keys to guarantee 100% isolation
    const updatedPayrollMap = { ...employeePayrollData };
    empKeys.forEach(k => {
      updatedPayrollMap[`${k}_${selectedPayrollCycle}`] = docData;
    });
    setEmployeePayrollData(updatedPayrollMap);
    localStorage.setItem('etegah_employee_payroll', JSON.stringify(updatedPayrollMap));

    try {
      // Save strictly under cycle-specific keys in Firestore employee_payroll collection
      const savePromises = [];
      empKeys.forEach(k => {
        savePromises.push(setDoc(doc(db, 'employee_payroll', `${k}_${selectedPayrollCycle}`), docData, { merge: true }));
      });

      // Update permanent baseSalary and shift times on employee document in 'users' collection
      if (empDocId) {
        savePromises.push(
          updateDoc(doc(db, 'users', empDocId), {
            baseSalary: payrollBaseSalary,
            checkIn: payrollCheckIn,
            checkOut: payrollCheckOut,
            updatedAt: serverTimestamp()
          }).catch(err => console.error('Error updating baseSalary in users col:', err))
        );
      }

      await Promise.all(savePromises);
      toast.success(`تم تحديث راتب وبيانات الموظف (${editingPayrollEmp.name || editingPayrollEmp.username}) لدورة (${getPayrollCycleLabel(selectedPayrollCycle)}) بنجاح 💾`);
    } catch (err) {
      console.error('Error saving payroll:', err);
      toast.success(`تم حفظ بيانات الموظف بنجاح 💾`);
    }
    setIsEditPayrollModalOpen(false);
    setEditingPayrollEmp(null);
  };

  const handleUploadFingerprintSheet = (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    const userRole = isAdmin ? '👑 الإدارة' : isCoordinator ? `📋 منسق الإدارة (${currentEmpUser?.name || 'منسق'})` : (currentEmpUser?.name || 'موظف');
    const now = new Date();
    const formattedNow = now.toLocaleDateString('ar-EG') + ' • ' + now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

    for (const file of files) {
      const isImg = file.type.startsWith('image/');
      const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.name.endsWith('.csv');
      const reader = new FileReader();
      reader.onload = async (event) => {
        const fileUrl = event.target.result;
        const newAtt = {
          id: 'fp_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
          name: file.name,
          type: isImg ? 'image' : isExcel ? 'excel' : 'file',
          size: (file.size / 1024).toFixed(1) + ' KB',
          url: fileUrl,
          uploadedAt: formattedNow,
          uploadedBy: userRole
        };
        const updatedList = [newAtt, ...fingerprintAttachments];
        setFingerprintAttachments(updatedList);
        localStorage.setItem('etegah_fingerprint_attachments', JSON.stringify(updatedList));
        try {
          await setDoc(doc(db, 'payroll_settings', 'fingerprint_config'), {
            attachments: updatedList.slice(0, 30),
            updatedAt: serverTimestamp()
          }, { merge: true });
        } catch(err) {}
        toast.success(`تم رفع شيت البصمة (${file.name}) بنجاح ⏰`);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
    setIsFingerprintUploadModalOpen(false);
  };

  const handleExportPayrollToExcel = () => {
    try {
      const targetEmps = (employees || []).filter(e => e.role !== 'admin');
      const excelRows = targetEmps.map((emp, idx) => {
        const p = employeePayrollData[emp.uid] || employeePayrollData[emp.id] || {};
        const base = parseFloat(p.baseSalary) || 0;
        const adv = parseFloat(p.advances) || 0;
        const kpi = parseFloat(p.kpiDeduction) || 0;
        const lateD = parseFloat(p.lateDeduction) || 0;
        const net = Math.max(0, base - adv - kpi - lateD);

        return {
          '#': idx + 1,
          'اسم الموظف': emp.username || emp.name,
          'تاريخ التعيين': formatDate(emp.createdAt),
          'التدرج الوظيفي': emp.jobTitle || (emp.role === 'coordinator' ? 'منسق إدارة' : emp.role === 'leader' ? 'ليدر' : emp.role === 'customer_service' ? 'خدمة عملاء' : 'موظف'),
          'المرتب الثابت (ج.م)': p.baseSalary || 0,
          'بصمة الحضور': p.checkIn || '09:00 AM',
          'بصمة الانصراف': p.checkOut || '05:00 PM',
          'أيام التأخير': p.lateDays || 0,
          'خصم التأخيرات (ج.م)': p.lateDeduction || 0,
          'السلف المسحوبة (ج.م)': p.advances || 0,
          'خصومات KPI (ج.م)': p.kpiDeduction || 0,
          'صافي القبض المستحق (ج.م)': net,
          'ملاحظات': p.notes || ''
        };
      });

      const wb = XLSX.utils.book_new();
      const ws = XLSX.utils.json_to_sheet(excelRows);
      XLSX.utils.book_append_sheet(wb, ws, 'جدول الرواتب والبصمة');
      XLSX.writeFile(wb, `جدول_رواتب_وحضور_الموظفين_${new Date().toISOString().slice(0, 10)}.xlsx`);
      toast.success('تم تحميل جدول الرواتب المعتمد إلى Excel بنجاح 📥');
    } catch(e) {
      toast.error('حدث خطأ أثناء تحميل ملف الرواتب');
    }
  };

  // --- V2.26 MONTHLY CYCLES & CYCLE RESET ENGINE ---
  const getPayrollCycleKey = (d = new Date()) => {
    const date = new Date(d);
    let y = date.getFullYear();
    let m = date.getMonth() + 1;
    if (date.getDate() < 20) {
      m -= 1;
      if (m === 0) { m = 12; y -= 1; }
    }
    const key = `${y}-${m < 10 ? '0' + m : m}`;
    return key < '2026-09' ? '2026-09' : key;
  };

  const getPayrollCycleLabel = (cycleKey) => {
    if (!cycleKey) return '';
    const parts = cycleKey.split('-');
    const y = parts[0];
    const m = parseInt(parts[1], 10);
    const monthsAr = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
    const monthName = monthsAr[m - 1] || m;
    return `دورة 20 ${monthName} ${y}`;
  };

  const getPreviousPayrollCycles = () => {
    const list = [];
    const currentKey = getPayrollCycleKey();
    const minCycle = '2026-09';
    
    // Build list of valid cycles starting from 2026-09
    const monthsAr = ['سبتمبر 2026', 'أكتوبر 2026', 'نوفمبر 2026', 'ديسمبر 2026'];
    const cycleKeys = ['2026-09', '2026-10', '2026-11', '2026-12'];

    cycleKeys.forEach((key, idx) => {
      if (key >= minCycle && key !== currentKey && !list.some(item => item.key === key)) {
        list.push({ key, label: getPayrollCycleLabel(key) });
      }
    });

    return list;
  };

  const getEmployeePayrollForCycle = (emp, cycleKey) => {
    if (!emp) return {};
    const empId = emp.id || emp.uid;
    const empUid = emp.uid || emp.id;

    // 1. Strict check for exact cycle-specific document
    if (cycleKey && employeePayrollData[`${empId}_${cycleKey}`]) {
      return employeePayrollData[`${empId}_${cycleKey}`];
    }
    if (cycleKey && empUid && employeePayrollData[`${empUid}_${cycleKey}`]) {
      return employeePayrollData[`${empUid}_${cycleKey}`];
    }

    // 2. Legacy check: only if the legacy doc matches the requested cycle
    const legacy = (empId && employeePayrollData[empId]) || (empUid && employeePayrollData[empUid]);
    if (legacy && legacy.cycle === cycleKey) {
      return legacy;
    }

    // 3. Fallback for new unedited cycle: baseSalary & shifts from emp profile, deductions default to blank
    return {
      baseSalary: emp.baseSalary || '',
      advances: '',
      kpiDeduction: '',
      lateDays: '',
      lateDeduction: '',
      checkIn: emp.checkIn || '09:00 AM',
      checkOut: emp.checkOut || '05:00 PM',
      notes: ''
    };
  };

  const getAvailableMonthsForSignals = (signalsList = []) => {
    const monthsSet = new Set();
    signalsList.forEach(sig => {
      const dateVal = sig.createdAtMillis ? new Date(sig.createdAtMillis) : (sig.createdAt?.seconds ? new Date(sig.createdAt.seconds * 1000) : null);
      if (dateVal && !isNaN(dateVal.getTime())) {
        const y = dateVal.getFullYear();
        const m = dateVal.getMonth() + 1;
        monthsSet.add(`${y}-${m < 10 ? '0' + m : m}`);
      }
    });
    const now = new Date();
    const currentM = `${now.getFullYear()}-${(now.getMonth() + 1) < 10 ? '0' + (now.getMonth() + 1) : (now.getMonth() + 1)}`;
    monthsSet.add(currentM);

    const monthsAr = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
    return Array.from(monthsSet).sort().reverse().map(key => {
      const parts = key.split('-');
      const y = parts[0];
      const mIdx = parseInt(parts[1], 10) - 1;
      return {
        key,
        label: `${monthsAr[mIdx] || parts[1]} ${y} ${key === currentM ? '(الشهر الحالي)' : ''}`
      };
    });
  };

  // --- V2.26 BULK DELETION & RECYCLE BIN ARCHIVING ---
  const handleSoftArchiveToRecycleBin = async (items, sourceKey, sourceTitle) => {
    const userRole = isAdmin 
      ? '👑 الإدارة' 
      : isCoordinator 
        ? `📋 منسق الإدارة (${currentEmpUser?.name || 'منسق'})` 
        : (currentEmpUser?.jobTitle === 'Customer Service' || currentEmpUser?.role === 'customer_service')
          ? `${currentEmpUser?.name || 'موظف'} (خدمة عملاء)`
          : `${currentEmpUser?.name || 'موظف'}`;
    const now = new Date().toISOString();

    const promises = items.map(item => {
      const binId = `recycle_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
      const titleStr = item.stockName 
        ? `${item.stockName} (${item.stockCode || ''})` 
        : item.symbol 
          ? `${item.symbol} (${item.marketType === 'options' ? 'عقد خيارات' : 'سهم أمريكي'})` 
          : item.empName || item.name || 'سجل محذوف';

      return setDoc(doc(db, 'recycle_bin', binId), {
        id: binId,
        source: sourceKey,
        sourceTitle: sourceTitle,
        itemType: sourceKey,
        type: sourceKey,
        title: titleStr,
        name: titleStr,
        deletedBy: userRole,
        deletedAt: now,
        deletedAtFormatted: new Date().toLocaleDateString('ar-EG') + ' • ' + new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' }),
        data: item,
        status: 'archived'
      });
    });

    await Promise.all(promises);
  };

