  const handleOpenAddBuffetItem = (item = null) => {
    if (item) {
      setEditingBuffetItem(item);
      setBuffetItemName(item.itemName || '');
      setBuffetItemTotalQty(item.totalQty || '');
      setBuffetItemUsedQty(item.usedQty || '');
      setBuffetItemRemainingQty(item.remainingQty || '');
      setBuffetItemNotes(item.notes || '');
      setBuffetItemCost(item.cost || item.itemPrice || '');
      setBuffetItemImage(item.imageUrl || null);
    } else {
      setEditingBuffetItem(null);
      setBuffetItemName('');
      setBuffetItemTotalQty('');
      setBuffetItemUsedQty('');
      setBuffetItemRemainingQty('');
      setBuffetItemNotes('');
      setBuffetItemCost('');
      setBuffetItemImage(null);
    }
    setIsAddBuffetItemModalOpen(true);
  };

  const handleSaveBuffetItem = async (e) => {
    if (e && e.preventDefault) e.preventDefault();

    // 1-Click Auto Batch Extraction when image/paste is attached without manual name entry
    if (buffetItemImage && !buffetItemName.trim() && !editingBuffetItem) {
      // INSTANT 0ms MODAL CLOSE & IMMEDIATE UPDATE
      const imageToExtract = buffetItemImage;
      setIsAddBuffetItemModalOpen(false);
      setBuffetItemImage(null);
      setBuffetSaving(false);
      toast.success('تم إغلاق النافذة وسحب بيانات الفاتورة إلى الشيت فوراً ⚡');

      // Async background OCR extraction & batch save
      (async () => {
        try {
          const compressedImg = await compressImageDataUrl(imageToExtract, 1000, 1000, 0.7);
          const ocrText = await performOcrOnImage(compressedImg);
          const extractedItems = extractInvoiceItemsFromText(ocrText);
          if (extractedItems && extractedItems.length > 0) {
            handleSaveAllExtractedInvoiceItems(extractedItems, imageToExtract, 'inventory');
          }
        } catch (err) {
          console.warn('Auto OCR extraction background fallback:', err);
        }
      })();
      return;
    }

    let finalName = buffetItemName.trim();
    if (!finalName) {
      if (buffetItemImage) {
        finalName = '🧾 فاتورة / سكرين شوت صنف بوفيه';
      } else if (buffetItemNotes.trim()) {
        finalName = `📝 ${buffetItemNotes.trim().slice(0, 30)}`;
      } else {
        finalName = '☕ صنف بوفيه جديد';
      }
    }

    setBuffetSaving(true);
    try {
      const now = new Date();
      const formattedNow = now.toLocaleDateString('ar-EG') + ' • ' + now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
      const userRole = isAdmin ? '👑 الإدارة' : isCoordinator ? `📋 منسق الإدارة (${currentEmpUser?.name || 'منسق'})` : (currentEmpUser?.name || 'موظف');

      let remaining = buffetItemRemainingQty.trim();
      if (!remaining && buffetItemTotalQty && buffetItemUsedQty) {
        const t = parseFloat(buffetItemTotalQty);
        const u = parseFloat(buffetItemUsedQty);
        if (!isNaN(t) && !isNaN(u)) {
          remaining = String(Math.max(0, t - u));
        }
      }

      // Fast Image Compression (5MB -> ~50KB)
      const compressedImage = await compressImageDataUrl(buffetItemImage, 900, 900, 0.65);

      const itemData = {
        itemName: finalName,
        totalQty: buffetItemTotalQty.trim() || '-',
        cost: buffetItemCost.trim() || '',
        usedQty: buffetItemUsedQty.trim() || '-',
        remainingQty: remaining || '-',
        notes: buffetItemNotes.trim(),
        imageUrl: compressedImage || '',
        updatedAt: serverTimestamp(),
        updatedBy: userRole,
        updatedDateTime: formattedNow
      };

      // 0ms Optimistic UI Update
      const targetId = editingBuffetItem?.id || ('item_' + Date.now() + Math.random().toString(36).substring(2, 6));
      const optimisticItem = { id: targetId, ...itemData };
      const updatedList = editingBuffetItem 
        ? buffetInventory.map(i => i.id === editingBuffetItem.id ? optimisticItem : i)
        : [optimisticItem, ...buffetInventory];
      setBuffetInventory(updatedList);
      localStorage.setItem('etegah_buffet_inventory', JSON.stringify(updatedList));

      setIsAddBuffetItemModalOpen(false);
      setEditingBuffetItem(null);
      setBuffetItemImage(null);
      toast.success('تم حفظ وتحديث صنف البوفيه فوراً ☕✨');

      // Asynchronous background Firestore save (never blocks UI)
      (async () => {
        try {
          if (editingBuffetItem && editingBuffetItem.id && !editingBuffetItem.id.startsWith('item_')) {
            await updateDoc(doc(db, 'buffet_inventory', editingBuffetItem.id), itemData);
          } else {
            itemData.createdAt = serverTimestamp();
            itemData.createdAtMillis = Date.now();
            itemData.order = buffetInventory.length + 1;
            await addDoc(collection(db, 'buffet_inventory'), itemData);
          }
        } catch(err) {
          console.warn('Background Firestore save error:', err);
        }
      })();
    } catch (err) {
      console.error('Error saving buffet item:', err);
      toast.error('حدث خطأ أثناء حفظ الصنف');
    } finally {
      setBuffetSaving(false);
    }
  };

  
  const handleBulkDeleteInventory = async () => {
    if (selectedInventoryIds.length === 0) return;
    if (!window.confirm(`هل أنت متأكد من حذف ${selectedInventoryIds.length} أصناف من مخزون البوفيه بنقرة واحدة ونقلها لسلة المهملات؟`)) return;
    const idsToDelete = [...selectedInventoryIds];
    const deleter = getCurrentDeleterInfo();
    const nowFormatted = new Date().toLocaleDateString('ar-EG') + ' • ' + new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
    
    // 0ms Instant Optimistic State Update
    const updatedList = buffetInventory.filter(i => !idsToDelete.includes(i.id));
    setBuffetInventory(updatedList);
    setSelectedInventoryIds([]);
    localStorage.setItem('etegah_buffet_inventory', JSON.stringify(updatedList));
    toast.success(`🎉 تم حذف ${idsToDelete.length} أصناف ونقلها لسلة المهملات لدى الإدارة!`);

    // Atomic writeBatch in Firestore background (delete + log to recycle_bin)
    (async () => {
      try {
        const batch = writeBatch(db);
        let count = 0;
        for (const id of idsToDelete) {
          if (id && !id.startsWith('item_')) {
            const itemObj = buffetInventory.find(i => i.id === id);
            batch.delete(doc(db, 'buffet_inventory', id));
            const binRef = doc(collection(db, 'recycle_bin'), id);
            batch.set(binRef, {
              type: 'buffet_inventory',
              title: itemObj?.itemName || 'صنف بوفيه',
              name: itemObj?.itemName || 'صنف بوفيه',
              originalCollection: 'buffet_inventory',
              data: itemObj || {},
              deletedBy: deleter.label,
              deletedByUid: deleter.uid,
              deletedAt: serverTimestamp(),
              deletedAtFormatted: nowFormatted
            });
            count++;
          }
        }
        if (count > 0) {
          await batch.commit();
        }
      } catch (err) {
        console.warn('Background batch delete error:', err);
      }
    })();
  };

